    copy = test.year().addToCopy(0);
    check(copy, 1972, 6, 9);

    copy = test.year().addToCopy(292277023 - 1972);
    check(copy, 292277023, 6, 9);

    try {
        test.year().addToCopy(292278993 - 1972 + 1);
        fail();
}
}

