    DateTime expect = null;
    expect = new DateTime(2004, 1, 1, 0, 0, 0, 0, UTC);
    // removed other assertion

    expect = new DateTime(1922, 1, 1, 0, 0, 0, 0, UTC);
    // removed other assertion

